window.ox.install(({action})=>{action('limitItemQuantity',{async invoke(args){const wait=async fn=>{const end=Date.now()+12000;while(Date.now()<end){const r=fn();if(r)return r;await new Promise(r=>setTimeout(r,150));}throw Error('Cart update not confirmed');};const cartButton=await wait(()=>document.querySelector('button[aria-label^="Cart with"]'));cartButton.click();const d=await wait(()=>document.querySelector('[aria-labelledby="cart-label"]'));await wait(()=>{const count=Number(cartButton.getAttribute('aria-label').match(/\d+/)?.[0]);return [...d.querySelectorAll('li [role="spinbutton"]')].reduce((n,e)=>n+Number(e.getAttribute('aria-valuenow')),0)===count;});const rows=()=>[...d.querySelectorAll('li')].filter(e=>e.querySelector('h2.name')?.textContent.trim()===args.itemName);await wait(()=>rows().length>0);const count=rows().length;if(count<args.quantity||count>10)throw Error('Unexpected item count');for(let n=count;n>args.quantity;n--){const list=rows();if(list.length!==n||list.some(e=>e.querySelector('[role="spinbutton"]')?.getAttribute('aria-valuenow')!=='1'))throw Error('Cart changed unexpectedly');const row=list[list.length-1],id=row.getAttribute('aria-labelledby'),b=row.querySelector('button[aria-label="Remove modifier"]');if(!b||b.disabled)throw Error('Remove control unavailable');b.click();await wait(()=>!d.querySelector('li[aria-labelledby="'+CSS.escape(id)+'"]')&&rows().length===n-1);}return {cartSummary:d.innerText};}});action('reviewCheckout',{async invoke(){const end=Date.now()+20000;while(Date.now()<end){const text=document.body.innerText;if(/payment|contact information|place order/i.test(text)&&document.querySelector('input,button'))return {summary:text.slice(-14000)};await new Promise(r=>setTimeout(r,200));}throw Error('Checkout form not ready');}});action('inspectCart',{async invoke(){const end=Date.now()+12000;while(Date.now()<end&&!document.querySelector('button[aria-label^="Cart with"]'))await new Promise(r=>setTimeout(r,200));const close=[...document.querySelectorAll('[role="dialog"] button[aria-label="Close"]')].find(e=>e.tabIndex!==-1);if(close)close.click();document.querySelector('button[aria-label^="Cart with"]')?.click();const deadline=Date.now()+8000;while(Date.now()<deadline){const rows=[...document.querySelectorAll('[aria-labelledby="cart-label"] li')];const sum=rows.reduce((n,e)=>n+Number(e.querySelector('[role="spinbutton"]')?.getAttribute('aria-valuenow')||0),0);const count=Number(document.querySelector('button[aria-label^="Cart with"]')?.getAttribute('aria-label')?.match(/\d+/)?.[0]);if(sum===count&&sum>0)break;await new Promise(r=>setTimeout(r,200));}return {cart:document.querySelector('button[aria-label^="Cart with"]')?.getAttribute('aria-label')||'',dialogs:[...document.querySelectorAll('[role="dialog"]')].map(e=>({title:JSON.stringify({title:e.querySelector('#menu-item-modal-header')?.textContent,role:e.getAttribute('role'),labelledby:e.getAttribute('aria-labelledby'),spin:!!e.querySelector('[role="spinbutton"]'),ctaDisabled:e.querySelector('[data-testid="menu-item-cart-cta"]')?.disabled}),text:e.innerText.slice(0,7000)+' ROWS: '+[...e.querySelectorAll('li')].map(r=>r.outerHTML.slice(0,6500)).join('')})),ctas:[...document.querySelectorAll('button,a')].filter(e=>/checkout|view order/i.test(e.textContent)).map(e=>({text:e.textContent.slice(0,100),tag:e.tagName,href:e.getAttribute('href')}))};}});action('listSessions',{async invoke(){const end=Date.now()+15000;while(Date.now()<end){if(document.querySelector('button[aria-label="Sign in"]')||(document.querySelector('#createToastAccount')&&document.querySelector('#yourInfoEmail')))return [];await new Promise(r=>setTimeout(r,200));}throw Error('Cannot establish current Toast account state');}}); action('login',{async invoke(){const b=document.querySelector('button[aria-label="Sign in"]');if(!b)throw Error('Sign-in control unavailable');b.click();const end=Date.now()+10000;while(Date.now()<end){if(document.querySelector('input[type="tel"],input[type="email"]'))return null;await new Promise(r=>setTimeout(r,200));}throw Error('Sign-in form not ready');}});action('addItem',{async invoke(args){
const wait=async(fn)=>{const end=Date.now()+20000;while(Date.now()<end){const v=fn();if(v)return v;await new Promise(r=>setTimeout(r,200));}throw Error('Menu readiness timed out: '+JSON.stringify({title:document.querySelector('#menu-item-modal-header')?.textContent,dialogCount:document.querySelectorAll('[role="dialog"]').length,cart:document.querySelector('button[aria-label^="Cart with"]')?.getAttribute('aria-label')}));};
const name=args.itemName; if(typeof name!=='string')throw Error('Missing normalized itemName; argument keys: '+Object.keys(args).join(',')); let d=await wait(()=>document.querySelector('[role="dialog"][aria-labelledby="menu-item-modal-header"]')||document.querySelector('button[aria-label="Add '+CSS.escape(name)+' to Cart"]'));
if(!d.matches('[role="dialog"]')){d.click();d=await wait(()=>document.querySelector('[role="dialog"][aria-labelledby="menu-item-modal-header"]'));}
d=await wait(()=>{const el=document.querySelector('[role="dialog"][aria-labelledby="menu-item-modal-header"]');return el?.querySelector('#menu-item-modal-header')?.textContent.trim()===name&&el.querySelector('[role="spinbutton"]')?el:null;});
if(d.querySelector('[role="spinbutton"]')?.getAttribute('aria-valuenow')!=='1')throw Error('Unexpected quantity');
if([...d.querySelectorAll('input')].some(e=>e.checked))throw Error('Unexpected selected options');
const button=d.querySelector('[data-testid="menu-item-cart-cta"]');if(!button||button.disabled||!button.textContent.includes('Add to Cart'))throw Error('Add control unavailable');
const cart=()=>document.querySelector('button[aria-label^="Cart with"]');const before=cart()?.getAttribute('aria-label');if(!before)throw Error('Cart count unavailable');
button.click(); const label=await wait(()=>{const v=cart()?.getAttribute('aria-label');return v&&v!==before&&!document.querySelector('[role="dialog"][aria-labelledby="menu-item-modal-header"]')?v:null;});return {added:true,itemName:name,cartLabel:label};
}});});